def max_sorted(arr, start, end):
    is_sorted = True
    for i in range(start, end):
        if arr[i] > arr[i+1]:
            is_sorted = False
            break
    if is_sorted:
        return end - start + 1
    length = end - start + 1
    if length == 1:
        return 1
    mid = start + (length // 2) - 1
    left = max_sorted(arr, start, mid)
    right = max_sorted(arr, mid+1, end)
    return max(left, right)

