for num in goalies:
    num_to_pos[num] = 'G'
for num in defenders:
    num_to_pos[num] = 'D'
for num in forwards:
    num_to_pos[num] = 'F'

total = 0
all_players = goalies + defenders + forwards

for x in all_players:
    pos = num_to_pos[x]
    g_count = bisect.bisect_right(goalies_sorted, 2 * x) - bisect.bisect_left(goalies_sorted, x)
    d_count = bisect.bisect_right(defenders_sorted, 2 * x) - bisect.bisect_left(defenders_sorted, x)
    f_count = bisect.bisect_right(forwards_sorted, 2 * x) - bisect.bisect_left(forwards_sorted, x)

    if pos == 'G':
        if d_count >= 2 and f_count >= 3:
            total += math.comb(d_count, 2) * math.comb(f_count, 3)
    elif pos == 'D':
        if g_count >= 1 and d_count >= 2 and f_count >= 3:
            total += g_count * (d_count - 1) * math.comb(f_count, 3)
    elif pos == 'F':
        if g_count >= 1 and d_count >= 2 and f_count >= 3:
            total += g_count * math.comb(d_count, 2) * math.comb(f_count - 1, 2)

