import heapq
from collections import defaultdict

def main():
    n = int(input())
    voters = []
    me = 0
    candidate_bribes = defaultdict(list)
    for _ in range(n):
        a, b = map(int, input().split())
        if a == 0:
            me += 1
        else:
            candidate_bribes[a].append(b)

    if not candidate_bribes:
        print(0)
        return

    other_candidates = []
    vote_counts = []
    prefix_sums = {}
    sorted_bribes = {}
    for c in candidate_bribes:
        bribes = candidate_bribes[c]
        bribes.sort()
        sorted_bribes[c] = bribes
        vote_counts.append(len(bribes))
        ps = [0] * (len(bribes) + 1)
        for i in range(len(bribes)):
            ps[i+1] = ps[i] + bribes[i]
        prefix_sums[c] = ps
        other_candidates.append(c)

    vote_counts.sort(reverse=True)
    if me > vote_counts[0]:
        print(0)
        return

    max_other = vote_counts[0]
    low = me + 1
    high = me + sum(len(v) for v in candidate_bribes.values())
    best_k = high

    while low <= high:
        mid = (low + high) // 2
        sum_required = 0
        for vc in vote_counts:
            if vc > mid -1:
                sum_required += (vc - (mid -1))
        if sum_required <= mid - me:
            best_k = mid
            high = mid -1
        else:
            low = mid +1

    K_min = best_k
    max_additional = 200
    max_K = K_min + max_additional
    min_cost = float('inf')

    for K in range(K_min, max_K +1):
        sum_required = 0
        sum_x = 0
        for c in other_candidates:
            vc = len(sorted_bribes[c])
            x_c = max(0, vc - (K-1))
            sum_x += x_c
            if x_c >0:
                sum_required += prefix_sums[c][x_c]
        if sum_x > (K - me):
            continue
        rem = (K - me) - sum_x
        if rem <0:
            continue

        heap = []
        for c in other_candidates:
            vc = len(sorted_bribes[c])
            x_c = max(0, vc - (K-1))
            if x_c < len(sorted_bribes[c]):
                heapq.heappush(heap, (sorted_bribes[c][x_c], c, x_c))

        optional_sum =0
        count =0
        temp_heap = []
        for entry in heap:
            heapq.heappush(temp_heap, entry)
        heap = temp_heap

        while count < rem and heap:
            cost, c, index = heapq.heappop(heap)
            optional_sum += cost
            count +=1
            if index +1 < len(sorted_bribes[c]):
                heapq.heappush(heap, (sorted_bribes[c][index+1], c, index+1))

        if count < rem:
            continue

        total_cost = sum_required + optional_sum
        if total_cost < min_cost:
            min_cost = total_cost

    print(min_cost if min_cost != float('inf') else 0)

if __name__ == "__main__":
    main()

